import{z as p,x as s,o as E,c as h,q as n,j as r,D as l,d as e,s as o,S as m,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"平面波与波矢","description":"","frontmatter":{"title":"平面波与波矢","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/plane-wave-k.md","filePath":"litho/plane-wave-k.md","lastUpdated":1791063341000}'),A={name:"litho/plane-wave-k.md"};function d(f,a,B,k,b,_){const i=s("Mermaid");return E(),h("div",null,[a[2]||(a[2]=n('<h1 id="平面波与波矢" tabindex="-1">平面波与波矢 <a class="header-anchor" href="#平面波与波矢" aria-label="Permalink to &quot;平面波与波矢&quot;">​</a></h1><div class="epigraph"><p>均匀介质里，相位只沿一个方向线性变化；波矢 $\\mathbf{k}$ 给出该方向的波长倒数与传播指向。</p><footer>—— 据 Born &amp; Wolf, Principles of Optics 对平面波与色散关系的表述整理</footer></div><p><a href="/litho/maxwell-to-wave">上一课</a>从无源均匀介质推出波动方程，时谐场满足亥姆霍兹方程。本课不重推旋度恒等式。缺口是：方程的特解长什么样？波矢 \\(\\mathbf{k}\\) 如何把方向、波长与频率绑在一起？后课的衍射、光瞳坐标与空间频率，都默认平面波是「基」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>亥姆霍兹 \\(\\nabla^2\\mathbf{E}+k^2\\mathbf{E}=0\\) 在无限均匀介质中最简单的解，是相位沿固定方向线性变化的场。若只停留在标量方程而不引入 \\(\\mathbf{k}\\)，无法说清「斜入射」「离轴方向」「横向空间频率」这些后课符号从哪来。缺口不是再写一遍麦克斯韦，而是把特解写成平面波，并把 \\(|k|\\) 与传播角绑死。</p><p>后一课程的 <a href="/litho/em-wave-index">单色波、折射率与光程</a> 会把 \\(n\\)、光程与相位积分再钉一次。本课先在均匀介质里完成几何：\\(\\mathbf{k}\\) 的方向就是等相位面的法向。</p><h3 id="波长与波数必须分开写" tabindex="-1">波长与波数必须分开写 <a class="header-anchor" href="#波长与波数必须分开写" aria-label="Permalink to &quot;波长与波数必须分开写&quot;">​</a></h3><p>角频率 \\(\\omega\\) 固定时，\\(k=|\\mathbf{k}|=\\omega/v=2\\pi/\\lambda\\)。真空波长 \\(\\lambda_0\\) 与介质波长 \\(\\lambda=\\lambda_0/n\\) 不是同一个数。口语里的「193 nm」几乎总是真空（或空气）标称值；介质里的振荡周期要除以 \\(n\\)。本课用 \\(k=n k_0\\)、\\(k_0=\\omega/c\\) 把这套约定先写进平面波。</p><p><span class="marginnote">数字实例：193 nm 的 ArF 光，\\(k_0=2\\pi/\\lambda_0\\approx 3.3\\times 10^7\\ \\mathrm{rad/m}\\)；进入 \\(n\\approx 1.44\\) 的熔融石英后 \\(k=n k_0\\)，介质波长缩到约 134 nm——光没有「变色」，振荡只是被介质压密了。</span></p><p><span class="marginnote">波矢沿相位增加最快的方向。各向同性介质里坡印廷矢量与 \\(\\mathbf{k}\\) 同向。后课光瞳上的每一点，对应一组平面波方向，不是对应一个「光线颜色」。</span></p><p><span class="marginnote">术语翻译：波矢 \\(\\mathbf{k}\\) 是「方向 + 疏密」的二合一标签——箭头指向相位增加最快的方向，长度等于 \\(2\\pi/\\lambda\\)，即每米塞进多少个 \\(2\\pi\\) 的相位。看到 \\(\\mathbf{k}\\) 就同时读出「往哪走、多密」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>平面波（取电场某一 Cartesian 分量）：</p> \\[E(\\mathbf{r},t)=\\mathrm{Re}\\bigl\\{E_0\\,e^{i(\\mathbf{k}\\cdot\\mathbf{r}-\\omega t)}\\bigr\\}. \\]<p>代入亥姆霍兹方程，得色散关系 \\(|\\mathbf{k}|=k=n k_0\\)。等相位面是垂直于 \\(\\mathbf{k}\\) 的平面。沿 \\(\\mathbf{k}\\) 走 \\(\\Delta s\\)，相位变 \\(k\\Delta s\\)。对光轴 \\(z\\) 成角 \\(\\theta\\) 的平面波：\\(k_z=k\\cos\\theta\\)，\\(k_\\perp=k\\sin\\theta\\)。横向空间频率</p> \\[f=\\frac{k_\\perp}{2\\pi}=\\frac{n\\sin\\theta}{\\lambda_0} \\]<p>是后课夫琅禾费衍射与数值孔径的入口。本课不展开角谱积分，只钉：任意单色场可以想成许多不同 \\(\\mathbf{k}\\) 的叠加，每个平面波带着自己的方向。</p>',17)),(E(),r(m,null,{default:l(()=>[o(i,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20HH%5B%22%E4%BA%A5%E5%A7%86%E9%9C%8D%E5%85%B9%E6%96%B9%E7%A8%8B%22%5D%20--%3E%20PW%5B%22%E5%B9%B3%E9%9D%A2%E6%B3%A2%20exp(ik%C2%B7r)%22%5D%0A%20%20PW%20--%3E%20DISP%5B%22%7Ck%7C%20%3D%20n%20k0%22%5D%0A%20%20DISP%20--%3E%20THETA%5B%22k_perp%20%E5%AF%B9%E5%BA%94%20sin%20%CE%B8%22%5D%0A%20%20THETA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%85%89%E7%9E%B3%E4%B8%8E%E8%A1%8D%E5%B0%84%E7%BA%A7%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[e("麦克斯韦还要求横波条件 \\(\\mathbf{k}\\cdot\\mathbf{E}=0\\)。本课先承认电场在垂直 \\(\\mathbf{k}\\) 的平面内；两个正交分量如何命名，是下一课 "),t("a",{href:"/litho/polarization-states"},"偏振：线、圆与椭圆"),e("。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"有限孔径上的场不是严格单一平面波，而是一包 \\(\\mathbf{k}\\)。投影物镜在瞳面选通一部分横向波矢，物面图形的每个空间频率分量按不同角度传播，再在像面叠加。这是后课衍射语言的几何骨架；本课不把成像积分写出来。",-1)),(E(),r(m,null,{default:l(()=>[o(i,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E7%89%A9%E9%9D%A2%E5%9B%BE%E5%BD%A2%22%5D%20--%3E%20SF%5B%22%E5%88%86%E8%A7%A3%E6%88%90%E7%A9%BA%E9%97%B4%E9%A2%91%E7%8E%87%E5%88%86%E9%87%8F%22%5D%0A%20%20SF%20--%3E%20PW%5B%22%E6%AF%8F%E4%B8%AA%E5%88%86%E9%87%8F%20%3D%20%E4%B8%80%E4%B8%AA%E6%96%B9%E5%90%91%E7%9A%84%E5%B9%B3%E9%9D%A2%E6%B3%A2%22%5D%0A%20%20PW%20--%3E%20PUP%7B%22k_perp%20%E5%9C%A8%E5%85%89%E7%9E%B3%E5%86%85%3F%22%7D%0A%20%20PUP%20--%20%22%E6%98%AF%22%20--%3E%20IM%5B%22%E5%88%B0%E8%BE%BE%E5%83%8F%E9%9D%A2%E5%8F%82%E4%B8%8E%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20PUP%20--%20%22%E5%90%A6%22%20--%3E%20CUT%5B%22%E8%A2%AB%E5%85%89%E7%9E%B3%E5%88%87%E6%8E%89%22%5D%0A%20%20IM%20--%3E%20AIR%5B%22%E5%90%88%E6%88%90%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%0A%20%20CUT%20--%3E%20BLUR%5B%22%E9%AB%98%E9%A2%91%E7%BC%BA%E5%A4%B1%20%E7%BB%86%E8%8A%82%E5%8F%98%E7%B3%8A%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>平面波也是理解折射的预备：界面两侧切向 \\(\\mathbf{k}\\) 连续（从而 \\(n\\sin\\theta\\) 连续），法向 \\(k_z\\) 随 \\(n\\) 改变。下一课之后的 <a href="/litho/fresnel-coefficients">菲涅尔系数</a> 都建立在这套分解上。没有 \\(\\mathbf{k}\\)，斯涅尔定律只是几何口诀，没有波动来源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课仍是均匀、无界介质里的特解。有限光束是许多 \\(\\mathbf{k}\\) 的窄包络；相干长度与带宽在 <a href="/litho/coherence-length-prep">相干长度与光源带宽预备</a> 才讨论。也不处理导模、光子晶体等非均匀结构的离散谱。</p><p>标量写法暂时略去偏振椭圆。几何光线是 \\(|\\mathbf{k}|\\) 很大、包络缓慢时的极限；何时必须回到波动，见本课程末课。后课默认：提到「一个方向的单色光」，就是一个 \\(\\mathbf{k}\\)；空间频率先写成 \\(n\\sin\\theta/\\lambda_0\\)。</p><p><span class="marginnote">常见误区：以为「193 nm」指光在玻璃里的波长。标称波长几乎都是真空值，进介质后 \\(\\lambda=\\lambda_0/n\\)。写光程与相位积分时若用错这一个数，所有相位账都会整体错一个因子 \\(n\\)。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>平面波是均匀介质里亥姆霍兹的特解；\\(|\\mathbf{k}|=nk_0=2\\pi/\\lambda\\)。</li><li>横向分量 \\(k_\\perp\\) 与传播角通过 \\(n\\sin\\theta/\\lambda_0\\) 进入后课空间频率。</li><li>任意场可分解为平面波叠加；光瞳即对 \\(\\mathbf{k}\\) 的选择。</li><li>横波条件留给偏振课；界面振幅比留给菲涅尔课。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>；Hecht, <em>Optics</em> 第 2 章。</li></ul>',7))])}const P=p(A,[["render",d]]);export{D as __pageData,P as default};
